--đã chạy-- Điều kiện: 01..10. Bước 1 tạo cấu trúc đơn thuốc.
-- productID CHƯA có FK vì repository chưa có DDL inventory.
-- BẮT BUỘC chốt schema kho và áp dụng 14_medical_prescription_inventory_fk.sql
-- trước khi bật chức năng kê đơn/ghi dữ liệu. Không tạo sản phẩm giả thay module kho.
BEGIN;
CREATE TABLE IF NOT EXISTS medical."prescriptions" (
    "prescriptionID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "visitID" BIGINT NOT NULL REFERENCES medical."medicalVisits"("visitID") ON DELETE RESTRICT,
    "veterinarianID" BIGINT NOT NULL REFERENCES clinic."veterinarians"("veterinarianID") ON DELETE RESTRICT,
    "prescriptionNumber" VARCHAR(30) NOT NULL UNIQUE CHECK (length(trim("prescriptionNumber")) > 0),
    "prescribedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "generalInstruction" TEXT,
    "status" VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CHECK ("status" IN ('ACTIVE', 'CANCELLED')),
    "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS medical."prescriptionItems" (
    "prescriptionItemID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "prescriptionID" BIGINT NOT NULL REFERENCES medical."prescriptions"("prescriptionID") ON DELETE RESTRICT,
    "productID" BIGINT NOT NULL CHECK ("productID" > 0),
    "quantity" NUMERIC(12,3) NOT NULL CHECK ("quantity" > 0),
    "dose" VARCHAR(150) NOT NULL CHECK (length(trim("dose")) > 0),
    "frequency" VARCHAR(150) NOT NULL CHECK (length(trim("frequency")) > 0),
    "durationDays" INTEGER NOT NULL CHECK ("durationDays" > 0),
    "route" VARCHAR(100) NOT NULL CHECK (length(trim("route")) > 0),
    "instruction" TEXT
);
CREATE INDEX IF NOT EXISTS "idxPrescriptionsVisit" ON medical."prescriptions" ("visitID");
CREATE INDEX IF NOT EXISTS "idxPrescriptionsVetDate" ON medical."prescriptions" ("veterinarianID", "prescribedAt");
CREATE INDEX IF NOT EXISTS "idxPrescriptionItemsPrescription" ON medical."prescriptionItems" ("prescriptionID");
CREATE INDEX IF NOT EXISTS "idxPrescriptionItemsProduct" ON medical."prescriptionItems" ("productID");
COMMENT ON COLUMN medical."prescriptionItems"."productID" IS
    'Khóa ngoại inventory.products được bổ sung bằng file 14 sau khi nhóm kho chốt DDL. Chưa bật ghi đơn nếu chưa có FK.';
-- Backend: thuốc phải active và có MedicineProfile; đơn phải có ít nhất một item;
-- người kê có quyền trên ca; lưu header/items nguyên tử; không tự trừ kho khi lưu đơn.
COMMIT;
